def _ensure_rider(store, rid):
    rec = store.riders.get(rid)
    if not rec:
        raise ApiError("ERR_NOT_FOUND", f"Rider {rid} not found")
    return rec


def _new_rider(name, phone, clock):
    now = clock.now_iso()
    return {
        "id": new_uuid(),
        "name": name,
        "phone": phone,
        "status": "OFFLINE",
        "on_time_rate": 1.0,
