def _add_to_route_group(store, clock, rider, assignment):
    """Attach assignment to an existing ACTIVE group within 500 m, or leave solo."""
    order = store.orders[assignment["order_id"]]
    pickup = store.restaurants[order["restaurant_id"]]
    for group in store.route_groups.values():
        if group["rider_id"] != rider["id"] or group["status"] != "ACTIVE":
            continue
        for peer_id in group["assignment_ids"]:
            peer = store.assignments.get(peer_id)
            if not peer:
                continue
            if peer["status"] not in {"OFFERED", "ACCEPTED"}:
                continue
            peer_order = store.orders.get(peer["order_id"])
            if not peer_order:
                continue
            peer_pickup = store.restaurants.get(peer_order["restaurant_id"])
            if not peer_pickup:
                continue
            if distance_metres(
                peer_pickup["lat"], peer_pickup["lng"], pickup["lat"], pickup["lng"]
            ) <= 500.0:
                group["assignment_ids"].append(assignment["id"])
                assignment["route_group_id"] = group["id"]
                return


def _create_or_get_route_group(store, clock, rider, assignment):
    """When a rider accepts an offer and is already ON_DELIVERY with an active route,
    consider merging; otherwise leave solo.
    """
    if rider["status"] == "ON_DELIVERY":
        _add_to_route_group(store, clock, rider, assignment)
    # Solo deliveries are not wrapped in a RouteGroup; route_group_id stays null.

