"""Work order routes — open / read / assign / request-info / submit-info / escalate / resolve / close."""
from __future__ import annotations

from flask import Blueprint

from .. import cascade
from ..auth import require_role
from ..envelope import envelope_object, expect_json_body
from ..errors import ApiError
from ..ids import new_uuid
from ..store import get_clock, get_store
from ..validators import opt_str, req_str

bp = Blueprint("work_orders", __name__, url_prefix="/api")


CATEGORIES = {
    "DELIVERY_LATE", "FOOD_QUALITY", "MISSING_ITEM",
    "RIDER_BEHAVIOR", "RESTAURANT_BEHAVIOR", "PAYMENT_ISSUE", "OTHER",
}
OPENED_BY_ROLES = {"CUSTOMER", "RIDER", "RESTAURANT", "CUSTOMER_SERVICE"}


def _ensure_wo(store, wid):
    rec = store.work_orders.get(wid)
    if not rec:
        raise ApiError("ERR_NOT_FOUND", f"WorkOrder {wid} not found")
    return rec


@bp.post("/work-orders")
def open_wo():
    uid, role = require_role({"Customer", "Rider", "Restaurant", "CustomerService", "PlatformAdmin"})
    body = expect_json_body()
    opened_by_role = req_str(body, "opened_by_role")
    if opened_by_role not in OPENED_BY_ROLES:
        raise ApiError("ERR_VALIDATION", "invalid opened_by_role")
    opened_by_id = req_str(body, "opened_by_id")
    category = req_str(body, "category")
    if category not in CATEGORIES:
        raise ApiError("ERR_VALIDATION", "invalid category")

    # Identity match — opener-role/id must align with caller for non-CS/PA roles
    role_to_open_map = {
        "Customer": "CUSTOMER",
        "Rider": "RIDER",
        "Restaurant": "RESTAURANT",
        "CustomerService": "CUSTOMER_SERVICE",
        "PlatformAdmin": None,
    }
    expected_open = role_to_open_map.get(role)
    if role != "PlatformAdmin":
        if expected_open != opened_by_role:
            raise ApiError("ERR_FORBIDDEN", "opened_by_role must match caller role")
        if opened_by_id != uid:
            raise ApiError("ERR_FORBIDDEN", "opened_by_id must match X-User-ID")

    store = get_store()
    clock = get_clock()
    related_order_id = body.get("related_order_id")
    related_return_id = body.get("related_return_id")
    with store.lock:
        if related_order_id is not None:
            if related_order_id not in store.orders:
                raise ApiError("ERR_NOT_FOUND", "related_order_id not found")
        if related_return_id is not None:
            if related_return_id not in store.returns:
                raise ApiError("ERR_NOT_FOUND", "related_return_id not found")

        # If the opener role corresponds to a known entity, validate it exists.
        if opened_by_role == "CUSTOMER" and opened_by_id not in store.customers and role != "PlatformAdmin":
            raise ApiError("ERR_NOT_FOUND", "opened_by_id (customer) not found")
        if opened_by_role == "RIDER" and opened_by_id not in store.riders and role != "PlatformAdmin":
            raise ApiError("ERR_NOT_FOUND", "opened_by_id (rider) not found")
        if opened_by_role == "RESTAURANT" and opened_by_id not in store.restaurants and role != "PlatformAdmin":
            raise ApiError("ERR_NOT_FOUND", "opened_by_id (restaurant) not found")

        now = clock.now_iso()
        rec = {
            "id": new_uuid(),
            "opened_by_role": opened_by_role,
            "opened_by_id": opened_by_id,
            "category": category,
            "related_order_id": related_order_id,
            "related_return_id": related_return_id,
            "assigned_cs_user_id": None,
            "resolution_notes": None,
            "status": "OPEN",
            "created_at": now,
            "updated_at": now,
            "version": 1,
        }
        store.work_orders[rec["id"]] = rec
    return envelope_object(rec, status=201)


@bp.get("/work-orders/<wid>")
def read_wo(wid):
    uid, role = require_role({"PlatformAdmin", "CustomerService", "Customer", "Rider", "Restaurant"})
    store = get_store()
    with store.lock:
        rec = _ensure_wo(store, wid)
        # Opener can read their own ticket; CS/PA can read any.
        if role in {"Customer", "Rider", "Restaurant"}:
            if rec["opened_by_id"] != uid:
                raise ApiError("ERR_FORBIDDEN", "not your work order")
    return envelope_object(rec)


@bp.post("/work-orders/<wid>/assign")
def assign_wo(wid):
    uid, _ = require_role({"CustomerService", "PlatformAdmin"})
    store = get_store()
    clock = get_clock()
    with store.lock:
        rec = _ensure_wo(store, wid)
        if rec["status"] != "OPEN":
            raise ApiError("ERR_INVALID_STATE", "wo not OPEN")
        rec["assigned_cs_user_id"] = uid
        rec["status"] = "UNDER_REVIEW"
        cascade.touch(rec, clock)
    return envelope_object(rec)


@bp.post("/work-orders/<wid>/request-info")
def request_info_wo(wid):
    require_role({"CustomerService", "PlatformAdmin"})
    store = get_store()
    clock = get_clock()
    with store.lock:
        rec = _ensure_wo(store, wid)
        if rec["status"] != "UNDER_REVIEW":
            raise ApiError("ERR_INVALID_STATE", "wo not UNDER_REVIEW")
        rec["status"] = "AWAITING_INFO"
        cascade.touch(rec, clock)
    return envelope_object(rec)


@bp.post("/work-orders/<wid>/submit-info")
def submit_info_wo(wid):
    uid, _ = require_role({"Customer", "Rider", "Restaurant"})
    store = get_store()
    clock = get_clock()
    with store.lock:
        rec = _ensure_wo(store, wid)
        if uid != rec["opened_by_id"]:
            raise ApiError("ERR_FORBIDDEN", "not your work order")
        if rec["status"] != "AWAITING_INFO":
            raise ApiError("ERR_INVALID_STATE", "wo not AWAITING_INFO")
        rec["status"] = "UNDER_REVIEW"
        cascade.touch(rec, clock)
    return envelope_object(rec)


@bp.post("/work-orders/<wid>/escalate")
def escalate_wo(wid):
    require_role({"CustomerService", "PlatformAdmin"})
    store = get_store()
    clock = get_clock()
    with store.lock:
        rec = _ensure_wo(store, wid)
        if rec["status"] != "UNDER_REVIEW":
            raise ApiError("ERR_INVALID_STATE", "wo not UNDER_REVIEW")
        rec["status"] = "ESCALATED"
        cascade.touch(rec, clock)
    return envelope_object(rec)


@bp.post("/work-orders/<wid>/resolve")
def resolve_wo(wid):
    require_role({"CustomerService", "PlatformAdmin"})
    body = expect_json_body()
    notes = req_str(body, "resolution_notes")
    store = get_store()
    clock = get_clock()
    with store.lock:
        rec = _ensure_wo(store, wid)
        if rec["status"] not in {"UNDER_REVIEW", "ESCALATED"}:
            raise ApiError("ERR_INVALID_STATE", "wo not resolvable")
        if rec["assigned_cs_user_id"] is None:
            raise ApiError("ERR_INVALID_STATE", "wo not claimed")
        if rec.get("related_return_id"):
            related = store.returns.get(rec["related_return_id"])
            if related and related["status"] in {"REQUESTED", "ESCALATED"}:
                raise ApiError("ERR_RELATED_RETURN_UNRESOLVED", "related return unresolved")
        rec["resolution_notes"] = notes
        rec["status"] = "RESOLVED"
        cascade.touch(rec, clock)
    return envelope_object(rec)


@bp.post("/work-orders/<wid>/close")
def close_wo(wid):
    require_role({"CustomerService", "PlatformAdmin"})
    store = get_store()
    clock = get_clock()
    with store.lock:
        rec = _ensure_wo(store, wid)
        if rec["status"] != "RESOLVED":
            raise ApiError("ERR_INVALID_STATE", "wo not RESOLVED")
        rec["status"] = "CLOSED"
        cascade.touch(rec, clock)
    return envelope_object(rec)

"""Fines — read / list / waive."""
from __future__ import annotations

from flask import Blueprint, request

from .. import cascade
from ..auth import require_role
from ..envelope import envelope_array, envelope_object
from ..errors import ApiError
from ..pagination import apply as apply_pagination, parse as parse_pagination
from ..store import get_clock, get_store

bp = Blueprint("fines", __name__, url_prefix="/api")


SUBJECT_TYPES = {"RIDER", "RESTAURANT", "CUSTOMER"}
SETTLEMENT_STATUSES = {"PENDING", "SETTLED", "WAIVED"}


def _ensure_fine(store, fid):
    rec = store.fines.get(fid)
    if not rec:
        raise ApiError("ERR_NOT_FOUND", f"Fine {fid} not found")
    return rec


def _can_read(uid, role, fine):
    if role in {"PlatformAdmin", "CustomerService"}:
        return True
    if role == "Rider":
        return fine["subject_type"] == "RIDER" and fine["subject_id"] == uid
    if role == "Restaurant":
        return fine["subject_type"] == "RESTAURANT" and fine["subject_id"] == uid
    if role == "Customer":
        return fine["subject_type"] == "CUSTOMER" and fine["subject_id"] == uid
    return False


@bp.get("/fines/<fid>")
def read_fine(fid):
    uid, role = require_role({"PlatformAdmin", "CustomerService", "Rider", "Restaurant", "Customer"})
    store = get_store()
    with store.lock:
        rec = _ensure_fine(store, fid)
        if not _can_read(uid, role, rec):
            raise ApiError("ERR_FORBIDDEN", "not your fine")
    return envelope_object(rec)


@bp.get("/fines")
def list_fines():
    uid, role = require_role({"PlatformAdmin", "CustomerService", "Rider", "Restaurant", "Customer"})
    limit, offset = parse_pagination()
    subject_type = request.args.get("subject_type")
    subject_id = request.args.get("subject_id")
    settlement_status = request.args.get("settlement_status")
    if subject_type and subject_type not in SUBJECT_TYPES:
        raise ApiError("ERR_VALIDATION", "invalid subject_type")
    if settlement_status and settlement_status not in SETTLEMENT_STATUSES:
        raise ApiError("ERR_VALIDATION", "invalid settlement_status")

    if role in {"Rider", "Restaurant", "Customer"} and subject_id and subject_id != uid:
        raise ApiError("ERR_FORBIDDEN", "subject_id must match X-User-ID")

    store = get_store()
    with store.lock:
        items = list(store.fines.values())
        if role == "Rider":
            items = [f for f in items if f["subject_type"] == "RIDER" and f["subject_id"] == uid]
        elif role == "Restaurant":
            items = [f for f in items if f["subject_type"] == "RESTAURANT" and f["subject_id"] == uid]
        elif role == "Customer":
            items = [f for f in items if f["subject_type"] == "CUSTOMER" and f["subject_id"] == uid]
        if subject_type:
            items = [f for f in items if f["subject_type"] == subject_type]
        if subject_id:
            items = [f for f in items if f["subject_id"] == subject_id]
        if settlement_status:
            items = [f for f in items if f["settlement_status"] == settlement_status]
        window, total = apply_pagination(items, limit, offset)
    return envelope_array(window, limit=limit, offset=offset, total_count=total)


@bp.post("/fines/<fid>/waive")
def waive_fine(fid):
    require_role({"CustomerService", "PlatformAdmin"})
    store = get_store()
    clock = get_clock()
    with store.lock:
        rec = _ensure_fine(store, fid)
        if rec["settlement_status"] != "PENDING":
            raise ApiError("ERR_INVALID_STATE", "fine not PENDING")
        # Reverse ledger effect by subject type
        if rec["subject_type"] == "RIDER":
            rider = store.riders.get(rec["subject_id"])
            if rider:
                rider["wallet_balance_cents"] += rec["amount_cents"]
                cascade.touch(rider, clock)
        elif rec["subject_type"] == "CUSTOMER":
            customer = store.customers.get(rec["subject_id"])
            if customer:
                customer["credit_balance_cents"] += rec["amount_cents"]
                cascade.touch(customer, clock)
        elif rec["subject_type"] == "RESTAURANT":
            restaurant = store.restaurants.get(rec["subject_id"])
            if restaurant:
                restaurant["pending_settlement_cents"] += rec["amount_cents"]
                cascade.touch(restaurant, clock)
        rec["settlement_status"] = "WAIVED"
    return envelope_object(rec)

"""Rider endpoints."""
from __future__ import annotations

from flask import Blueprint

from .. import cascade
from ..auth import require_role
from ..envelope import envelope_object, expect_json_body
from ..errors import ApiError
from ..ids import new_uuid
from ..store import get_clock, get_store
from ..validators import req_str

bp = Blueprint("riders", __name__, url_prefix="/api")


RIDER_STATUSES = {"OFFLINE", "AVAILABLE", "ON_DELIVERY", "SUSPENDED"}


def _ensure_rider(store, rid):
    rec = store.riders.get(rid)
    if not rec:
        raise ApiError("ERR_NOT_FOUND", f"Rider {rid} not found")
    return rec


def _new_rider(name, phone, clock):
    now = clock.now_iso()
    return {
        "id": new_uuid(),
        "name": name,
        "phone": phone,
        "status": "OFFLINE",
        "on_time_rate": 1.0,
        "acceptance_rate": 1.0,
        "rating": 5.0,
        "wallet_balance_cents": 0,
        "bonus_tier": "BRONZE",
        "created_at": now,
        "updated_at": now,
        "version": 1,
    }


@bp.post("/riders")
def register_rider():
    require_role({"PlatformAdmin"})
    body = expect_json_body()
    name = req_str(body, "name").strip()
    phone = req_str(body, "phone").strip()
    if not name or not phone:
        raise ApiError("ERR_VALIDATION", "name/phone required")
    store = get_store()
    with store.lock:
        if phone in store.rider_phones:
            raise ApiError("ERR_VALIDATION", "rider phone already in use")
        rec = _new_rider(name, phone, get_clock())
        store.riders[rec["id"]] = rec
        store.rider_phones.add(phone)
    return envelope_object(rec, status=201)


@bp.get("/riders/<rid>")
def read_rider(rid):
    uid, role = require_role({"PlatformAdmin", "Rider", "CustomerService"})
    store = get_store()
    with store.lock:
        rec = _ensure_rider(store, rid)
        if role == "Rider" and uid != rec["id"]:
            raise ApiError("ERR_FORBIDDEN", "Rider may only read own record")
    return envelope_object(rec)


@bp.post("/riders/<rid>/go-online")
def go_online(rid):
    uid, _ = require_role({"Rider"})
    store = get_store()
    with store.lock:
        rec = _ensure_rider(store, rid)
        if uid != rec["id"]:
            raise ApiError("ERR_FORBIDDEN", "Rider may only act on self")
        if rec["status"] != "OFFLINE":
            raise ApiError("ERR_INVALID_STATE", "rider not OFFLINE")
        rec["status"] = "AVAILABLE"
        cascade.touch(rec, get_clock())
    return envelope_object(rec)


@bp.post("/riders/<rid>/go-offline")
def go_offline(rid):
    uid, _ = require_role({"Rider"})
    store = get_store()
    with store.lock:
        rec = _ensure_rider(store, rid)
        if uid != rec["id"]:
            raise ApiError("ERR_FORBIDDEN", "Rider may only act on self")
        if rec["status"] != "AVAILABLE":
            raise ApiError("ERR_INVALID_STATE", "rider not AVAILABLE")
        # No live assignments allowed
        for a in store.assignments.values():
            if a["rider_id"] == rid and a["status"] in {"OFFERED", "ACCEPTED", "PICKED_UP"}:
                raise ApiError("ERR_INVALID_STATE", "rider has active assignments")
        rec["status"] = "OFFLINE"
        cascade.touch(rec, get_clock())
    return envelope_object(rec)


@bp.post("/riders/<rid>/suspend")
def suspend_rider(rid):
    require_role({"PlatformAdmin"})
    store = get_store()
    with store.lock:
        rec = _ensure_rider(store, rid)
        if rec["status"] != "AVAILABLE":
            raise ApiError("ERR_INVALID_STATE", "rider not AVAILABLE")
        if not (rec["on_time_rate"] < 0.70 or rec["acceptance_rate"] < 0.50):
            raise ApiError("ERR_SUSPEND_CRITERIA_NOT_MET", "rider performance OK")
        rec["status"] = "SUSPENDED"
        cascade.touch(rec, get_clock())
    return envelope_object(rec)
